package report

import (
  "database/sql"
  "log"
  "os"
  "time"
)

func ExportAll(db *sql.DB, names []string) error {
  start := time.Now()
  defer log.Printf("export took %s", time.Since(start))
  for _, name := range names {
    f, err := os.Create(outPath(name))
    if err != nil {
      return err
    }
    defer f.Close()
    tx, err := db.Begin()
    if err != nil {
      return err
    }
    defer tx.Rollback()
    if err := writeRows(tx, f, name); err != nil {
      return err
    }
    if err := tx.Commit(); err != nil {
      return err
    }
  }
  return nil
}

