start := time.Now()
defer func() {
  log.Printf("export took %s", time.Since(start))
}()

func exportOne(db *sql.DB, name string) (err error) {
  f, err := os.Create(outPath(name))
  if err != nil {
    return err
  }
  defer func() {
    if cerr := f.Close(); cerr != nil && err == nil {
      err = fmt.Errorf("close %s: %w", name, cerr)
    }
  }()
  tx, err := db.Begin()
  if err != nil {
    return err
  }
  defer func() { _ = tx.Rollback() }()
  if err := writeRows(tx, f, name); err != nil {
    return err
  }
  return tx.Commit()
}
